import openpyxl, os, glob
from openpyxl.utils import get_column_letter
wb=openpyxl.load_workbook('/root/output/result.xlsx', data_only=False)
ws=wb['Data']
print('=== Data sheet rows 1-20, all columns A-L ===')
print('\t'.join(['row']+[get_column_letter(c) for c in range(1, ws.max_column+1)]))
for r in range(1,21):
    vals=[r]+[('' if ws.cell(r,c).value is None else str(ws.cell(r,c).value)) for c in range(1, ws.max_column+1)]
    print('\t'.join(map(str, vals)))
print('\n=== Data dimensions and possible year header cells in H:L ===')
for r in range(1,22):
    vals=[ws.cell(r,c).value for c in range(8,13)]
    if any(v is not None for v in vals):
        print('row', r, vals)
