for rng in ['H12:L17','H19:L24','H26:L31','H35:L40','H42:L47','H50:L50']:
    print('range', rng)
    for row in t[rng]:
        line=[]
        for cell in row:
            line.append(f'{cell.coordinate}:v={cell.value!r},fill={cell.fill.fill_type}/{cell.fill.fgColor.rgb or cell.fill.fgColor.indexed or cell.fill.fgColor.type}')
        print(' | '.join(line))
